<#
.SYNOPSIS
    Generate ordered driver WFP network rules for kfilter (static addresses).

.DESCRIPTION
    The driver's WFP callouts evaluate network rules in policy order (default
    deny plus explicit allows). Windows Firewall catch-all Block rules cannot
    express per-package default-deny with allow exceptions: explicit Blocks
    override Allow rules, so the previous version blocked its own exceptions.

    This script no longer creates firewall rules. It writes counted, exact-endpoint
    connect rules with mandatory risk reasons. Dynamic FQDN mediation is NOT
    implemented: resolve and review each address before passing it.

    -RemoveOnly deletes the legacy kfilter firewall Block rules installed by
    older versions of this script; it does not touch the driver.

.EXAMPLE
    .\Install-NetworkPolicy.ps1 -StaticAddresses 203.0.113.10 -Port 443 -Protocol tcp -Uses 2
#>
[CmdletBinding(SupportsShouldProcess, ConfirmImpact='High')]
param(
    [string[]]$StaticAddresses = @(),
    [ValidateRange(1, 65535)][int]$Port = 443,
    [ValidateSet('tcp', 'udp')][string]$Protocol = 'tcp',
    [ValidateRange(1, 32767)][int]$Uses = 1,
    [ValidateNotNullOrEmpty()][string]$Risk = 'login-endpoint',
    [string]$Out = 'network-policy.txt',
    [switch]$RemoveOnly,
    [string]$Prefix = 'KFilter containment'
)

$ErrorActionPreference = 'Stop'

if ($RemoveOnly) {
    foreach ($name in @("$Prefix outbound default deny", "$Prefix inbound default deny")) {
        Get-NetFirewallRule -DisplayName $name -ErrorAction SilentlyContinue |
            Remove-NetFirewallRule -Confirm:$false
    }
    Write-Host 'Removed legacy kfilter firewall block rules (if any).'
    return
}

if ($StaticAddresses.Count -eq 0) {
    throw 'Pass at least one reviewed host IP. Dynamic FQDN mediation is not implemented by the driver.'
}

$lines = New-Object System.Collections.Generic.List[string]
$lines.Add('# Generated by tools/Install-NetworkPolicy.ps1.')
$lines.Add('# Static, counted driver WFP rules; dynamic FQDN mediation is not implemented.')
$lines.Add('block-network on')
$lines.Add('network-default deny')
$lines.Add('network-loopback off')
foreach ($address in $StaticAddresses) {
    if ($address.Contains('/')) { throw "CIDR is not allowed; pass one host IP: $address" }
    $parsed = [System.Net.IPAddress]::Parse($address)
    $suffix = '/32'
    if ($parsed.AddressFamily -eq [System.Net.Sockets.AddressFamily]::InterNetworkV6) { $suffix = '/128' }
    $lines.Add("allow|network|ip=$address$suffix|port=$Port|proto=$Protocol|rights=connect|uses=$Uses|risk=$Risk")
}
$lines | Set-Content -Path $Out -Encoding UTF8
Write-Host "Wrote $Out. Merge it into policy\contain-policy.txt, then run:"
Write-Host "  kfilterctl policy policy\contain-policy.txt"
